h=20; w=13
G=[[4]*w for _ in range(h)]
pts=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# source template motif values; skip background 4
motif=[[-1,5,5],[8,5,8],[8,5,0]]
for r,c in pts:
    for dr in range(-1,2):
        for dc in range(-1,2):
            v=motif[dr+1][dc+1]
            if v!=-1 and 0<=r+dr<h and 0<=c+dc<w:
                G[r+dr][c+dc]=v
# preserve source shape at rows 11-13 cols 6-8 (already identical, though no stamp)
for row in G: print(' '.join(map(str,row)))

